"use client";

import {
  type ComponentProps,
  type KeyboardEvent,
  type ReactNode,
  useState,
} from "react";
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react";
import {
  useMotionValue,
  useMotionValueEvent,
  useTransform,
} from "motion/react";
import { cn } from "cn";

import { Button } from "@/components/ui/button";

import { DEFAULTS } from "./config";
import { anchorFold } from "./internal/anchor-fold.utils";
import { FoldBook } from "./internal/fold-book";
import {
  FoldCarouselContext,
  useFoldCarouselContext,
} from "./internal/fold-carousel.context";
import type { Fold, FoldVariantProps } from "./internal/fold-carousel.types";
import { FoldDoor } from "./internal/fold-door";
import { useFoldEngine } from "./internal/use-fold-engine";
import { wrap } from "./internal/wrap.utils";
import { useFoldCarousel } from "./use-fold-carousel";

const VARIANTS = {
  door: FoldDoor,
  book: FoldBook,
} satisfies Record<string, (props: FoldVariantProps) => ReactNode>;

export type FoldCarouselProps = ComponentProps<"div"> & {
  /**
   * One slide per item, each painted across both halves of the frame. Anything that fills a
   * box works, like `img` or `next/image` with `fill`.
   */
  slides: ReactNode[];
  /** Whether the last slide folds on to the first. */
  loop?: boolean;
  /** Seconds a turn takes to settle onto a slide. */
  duration?: number;
  /** The slide shown first. */
  defaultIndex?: number;
  /** Called with the slide a turn is heading for, as soon as the turn starts. */
  onIndexChange?: (index: number) => void;
};

/**
 * A carousel that folds from one slide to the next like a two-panel phone. It holds the
 * state, so put a `FoldCarouselFrame` and any controls inside it. Arrow keys change slides
 * while focus is inside.
 */
export function FoldCarousel({
  slides,
  loop = DEFAULTS.loop,
  duration = DEFAULTS.duration,
  defaultIndex = 0,
  onIndexChange,
  children,
  ...props
}: FoldCarouselProps) {
  const engine = useFoldEngine({
    count: slides.length,
    loop,
    duration,
    defaultIndex,
    onIndexChange,
  });
  const [fold, setFold] = useState<Fold>({
    from: engine.index,
    direction: 1,
  });

  // The fold this render shows, published for Motion. Measuring progress against it instead
  // of the raw position keeps the leaves from drawing a slide React has not mounted yet.
  const from = useMotionValue(fold.from);
  const direction = useMotionValue<number>(fold.direction);
  from.set(fold.from);
  direction.set(fold.direction);

  // Can sit just outside 0 to 1 while React catches up. Variants clamp it, and the clamp
  // lands on the same picture the other side of the swap draws.
  const progress = useTransform(
    () => direction.get() * (engine.position.get() - from.get()),
  );

  // Do not force React into step with `flushSync` here. Committing inside a motion value's
  // change event skips every subscriber after this one.
  useMotionValueEvent(engine.position, "change", (position) => {
    const anchored = anchorFold(fold, position);
    if (anchored !== fold) setFold(anchored);
  });

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      engine.prev();
    }
    if (event.key === "ArrowRight") {
      event.preventDefault();
      engine.next();
    }
  };

  return (
    <FoldCarouselContext value={{ ...engine, slides, fold, progress }}>
      <div
        role="region"
        aria-roledescription="carousel"
        data-slot="fold-carousel"
        onKeyDownCapture={handleKeyDown}
        {...props}
      >
        {children}
        {slides.length > 0 && (
          <div aria-live="polite" aria-atomic className="sr-only">
            Slide {engine.index + 1} of {slides.length}
          </div>
        )}
      </div>
    </FoldCarouselContext>
  );
}

export type FoldCarouselFrameProps = Omit<
  FoldVariantProps,
  "outgoing" | "incoming" | "progress" | "mirrored"
> & {
  /** `door` swings the next slide in behind the current one. `book` lays it underneath. */
  variant?: keyof typeof VARIANTS;
};

/** The folding picture. Reads its slides and progress from the surrounding `FoldCarousel`. */
export function FoldCarouselFrame({
  variant = "door",
  ...props
}: FoldCarouselFrameProps) {
  const { slides, fold, progress } = useFoldCarouselContext();
  if (!slides.length) return null;

  const at = (slide: number) => slides[wrap(slide, slides.length)];
  const Variant = VARIANTS[variant];

  return (
    <Variant
      role="group"
      aria-roledescription="slide"
      aria-label={`${wrap(fold.from, slides.length) + 1} of ${slides.length}`}
      data-slot="fold-carousel-frame"
      {...props}
      progress={progress}
      outgoing={at(fold.from)}
      incoming={at(fold.from + fold.direction)}
      mirrored={fold.direction < 0}
    />
  );
}

/**
 * Folds back one slide. Takes every `Button` prop, and children replace the icon. At the
 * first slide without a loop it stays focusable and does nothing.
 */
export function FoldCarouselPrevious({
  variant = "outline",
  size = "icon",
  className,
  children,
  onClick,
  ...props
}: ComponentProps<typeof Button>) {
  const { canPrev, prev } = useFoldCarousel();

  return (
    <Button
      data-slot="fold-carousel-previous"
      aria-label="Previous slide"
      variant={variant}
      size={size}
      disabled={!canPrev}
      focusableWhenDisabled
      className={cn("data-disabled:opacity-50", className)}
      onClick={(event) => {
        onClick?.(event);
        prev();
      }}
      {...props}
    >
      {children ?? <ChevronLeftIcon />}
    </Button>
  );
}

/**
 * Folds on one slide. Takes every `Button` prop, and children replace the icon. At the last
 * slide without a loop it stays focusable and does nothing.
 */
export function FoldCarouselNext({
  variant = "outline",
  size = "icon",
  className,
  children,
  onClick,
  ...props
}: ComponentProps<typeof Button>) {
  const { canNext, next } = useFoldCarousel();

  return (
    <Button
      data-slot="fold-carousel-next"
      aria-label="Next slide"
      variant={variant}
      size={size}
      disabled={!canNext}
      focusableWhenDisabled
      className={cn("data-disabled:opacity-50", className)}
      onClick={(event) => {
        onClick?.(event);
        next();
      }}
      {...props}
    >
      {children ?? <ChevronRightIcon />}
    </Button>
  );
}

import { useFoldCarouselContext } from "./internal/fold-carousel.context";

/**
 * Reads the surrounding `FoldCarousel`, for building your own controls like dots or a
 * counter. `index` is the slide the carousel is heading for, so it updates the moment a turn
 * starts.
 */
export function useFoldCarousel() {
  const { index, count, canPrev, canNext, prev, next, goTo } =
    useFoldCarouselContext();

  return { index, count, canPrev, canNext, prev, next, goTo };
}

/*
 * Values that are safe to tweak. Everything in `internal/` is geometry the fold's
 * pixel-exact slide swap depends on.
 */

/** Used when `FoldCarousel` or `FoldCarouselFrame` is given no value. */
export const DEFAULTS = {
  /** Width of one square panel, as any CSS length. The frame is two panels wide. */
  panelWidth: "min(23rem, 42vw)",
  /** Perspective distance, in panel widths. Lower is more dramatic. Must stay above 1. */
  depth: 88 / 23,
  /** Seconds a turn takes to settle onto a slide. */
  duration: 0.8,
  /** Whether the last slide folds on to the first. */
  loop: true,
};

/** How the `door` variant staggers its two leaves. */
export const DOOR = {
  /**
   * Where the incoming leaf starts, in degrees. Keep it a few degrees short of -90. Exactly
   * edge-on, browsers rasterise it inconsistently and the clip math divides by zero.
   */
  incomingFrom: -85,
  /**
   * The slice of the turn the incoming leaf moves over. A `bias` below 1 makes it lead and
   * settle slowly, above 1 makes it lag and then rush. Moving at a different rate from the
   * outgoing leaf is what makes the two read as separate depths.
   */
  incoming: { from: 0.15, to: 0.9, bias: 0.8 },
};

/** The progressive blur on a turning face. */
export const BLUR = {
  /** Radius at the panel's outer edge, in panel widths. */
  maxRadius: 0.09,
  /** Bends the ramp so the blur stays tight near the hinge. */
  curve: 1.35,
  /**
   * Blurred copies per face. More blends more smoothly and holds more textures. The radii
   * are fixed, so it never adds work per frame.
   */
  layers: 8,
};

/** The darkening on a turning face. */
export const SHADE = {
  /** Share of the panel next to the hinge that stays unshaded. */
  deadZone: 0.2,
  /** Bends the ramp so it stays light near the hinge and falls off fast after. */
  curve: 1.35,
  /** Pushes the far side to full black before it reaches the outer edge. */
  gain: 2,
};

import type { Fold } from "./fold-carousel.types";

/**
 * How near a slide counts as at rest, in slides. A spring lands a hair short of its target,
 * and without this slack, pushing back on a finished fold would un-finish it instead of
 * mirroring it. Half a degree of the 180° turn: invisible, and far above float error.
 */
const REST = 0.5 / 180;

/**
 * The fold on screen once `position` has been reached, in slides.
 *
 * Returns `fold` itself while the turn is still inside it, so callers can skip the update.
 * Otherwise it re-anchors on the slide the turn is nearest. Pushing back past where the fold
 * started is the only thing that flips `direction`.
 */
export function anchorFold(fold: Fold, position: number): Fold {
  const travelled = fold.direction * (position - fold.from);
  if (travelled >= -REST && travelled < 1 - REST) return fold;

  let direction = fold.direction;
  if (travelled < 0) direction = fold.direction === 1 ? -1 : 1;

  // At rest, anchor on the slide it landed on. Still moving, anchor behind it, so the fold
  // in progress is the one described.
  const nearest = Math.round(position);
  if (Math.abs(position - nearest) < REST) return { from: nearest, direction };

  return {
    from: direction > 0 ? Math.floor(position) : Math.ceil(position),
    direction,
  };
}

import { BLUR, SHADE } from "../config";

/*
 * The ramps a turning face is drawn with, ported from the reference shader:
 *   radius = 72 * motion * pow(edge, 1.35)
 *   darken = min(1, 2 * motion * pow(clamp((edge - 0.2) / 0.8), 1.35))
 * `edge` runs from 0 at the hinge to 1 at the panel's outer edge. Both are written for a
 * fully turned face, and the face's tilt scales them.
 */

/** How dark a fully turned face is at `edge`. */
export function shadeAlpha(edge: number) {
  const ramp = Math.max(0, (edge - SHADE.deadZone) / (1 - SHADE.deadZone));
  return Math.min(1, SHADE.gain * ramp ** SHADE.curve);
}

/**
 * Draws the shade for a face `tilt` of the way turned, using only opacity and a horizontal
 * stretch.
 *
 * The shader scales before it clamps. Fading alone scales after, which bakes the clamp's
 * corner in and shows as a dark line down the face. Stretching by `tilt ** (-1 / curve)`
 * applies the scale first, exactly. Below `1 / gain` the clamp cannot bind, so opacity
 * takes over and the stretch stays bounded.
 */
export function shadeTurn(tilt: number) {
  const turn = Math.max(tilt, 1 / SHADE.gain);

  return { opacity: tilt / turn, stretch: turn ** (-1 / SHADE.curve) };
}

/**
 * One blurred copy per step: a fixed radius, and a band `[from, to]` that means two things.
 * Across the panel it is where the copy fades in. Across the tilt it is when.
 *
 * Fixed radii are rasterised once, so a turn only changes opacity. The bands tile, so only
 * one copy is ever partway in.
 */
export const BLUR_LAYERS = Array.from({ length: BLUR.layers }, (_, index) => {
  const from = index / BLUR.layers;
  const to = (index + 1) / BLUR.layers;

  return { from, to, radius: BLUR.maxRadius * to ** BLUR.curve };
});

import { motion, useTransform } from "motion/react";

import { DEFAULTS } from "../config";
import type { FoldVariantProps } from "./fold-carousel.types";
import { FoldFace } from "./fold-face";
import { FoldStage } from "./fold-stage";
import { HINGE_OVERLAP, panels } from "./panels.utils";
import { SlideLayer } from "./slide-layer";
import { smoothstep } from "./smoothstep.utils";
import { LEAF_TURN, useLeaf } from "./use-leaf";

/**
 * The left half folds onto the right like a page, uncovering the next slide lying
 * underneath.
 *
 * One leaf carries `outgoing`'s left half on its front and lands on the right half carrying
 * `incoming`'s right half on its back. At progress 1 the frame is `incoming` on both halves,
 * so the carousel can swap slides with nothing moving.
 */
export function FoldBook({
  outgoing,
  incoming,
  progress,
  panelWidth,
  depth = DEFAULTS.depth,
  ...props
}: FoldVariantProps) {
  const angle = useTransform(() => LEAF_TURN * smoothstep(progress.get()));
  const leaf = useLeaf(angle, { depth });

  const face = {
    layerWidth: leaf.layerWidth,
    layerInset: leaf.layerInset,
    screenTop: leaf.screenTop,
  };
  const half = { width: panels(1), height: panels(1) };

  return (
    <FoldStage panelWidth={panelWidth} depth={depth} {...props}>
      {/* The incoming slide's left half, lying still under the fold. It is not turning, so
          it needs no shade or blur. */}
      <div
        style={{
          width: leaf.layerWidth,
          top: leaf.layerInset,
          bottom: leaf.layerInset,
          right: `calc(50% - ${HINGE_OVERLAP}rem)`,
        }}
        className="absolute overflow-hidden"
      >
        <SlideLayer slide={incoming} left={panels(0)} top={leaf.screenTop} />
      </div>

      {/* The leaf's body. Black, so the slivers the magnified fold reaches past the screen
          read as bezel. */}
      <motion.div
        style={{ rotateY: angle, ...half }}
        className="origin-right bg-black"
      />

      <FoldFace
        {...face}
        side={leaf.frontSide}
        slide={outgoing}
        clipPath={leaf.frontClip}
        tilt={leaf.frontTilt}
      />

      {/* The still half. Painted after the leaf's front so it covers that edge instead of
          meeting it on a fractional pixel. */}
      <div style={half} className="relative overflow-hidden bg-black">
        <SlideLayer
          slide={outgoing}
          left={panels(-1)}
          top={panels(0)}
          primary
        />
      </div>

      {/* Painted last, so the back comes down on top of the still half. */}
      <FoldFace
        {...face}
        side={leaf.backSide}
        slide={incoming}
        clipPath={leaf.backClip}
        tilt={leaf.backTilt}
      />
    </FoldStage>
  );
}

import { createContext, type ReactNode, use } from "react";
import type { MotionValue } from "motion/react";

import type { Fold } from "./fold-carousel.types";
import type { useFoldEngine } from "./use-fold-engine";

type FoldCarouselContextValue = ReturnType<typeof useFoldEngine> & {
  slides: ReactNode[];
  /** The fold on screen, which trails the engine's target while React catches up. */
  fold: Fold;
  /** How far through `fold` the turn is, 0 to 1. */
  progress: MotionValue<number>;
};

export const FoldCarouselContext =
  createContext<FoldCarouselContextValue | null>(null);

/** The surrounding carousel's full state. Throws outside a `FoldCarousel`. */
export function useFoldCarouselContext() {
  const context = use(FoldCarouselContext);
  if (!context) {
    throw new Error("Fold carousel parts must be used inside <FoldCarousel>.");
  }

  return context;
}

import type { ComponentProps, ReactNode } from "react";
import type { MotionValue } from "motion/react";

/** What every variant takes, so the frame can swap one for another. */
export type FoldVariantProps = ComponentProps<"div"> & {
  /** The slide on screen, painted once across both halves. */
  outgoing: ReactNode;
  /** The slide coming in. By the end of the turn it fills the frame. */
  incoming: ReactNode;
  /**
   * 0 with `outgoing` flat, 1 once `incoming` fills the frame, pixel for pixel what 0 draws
   * with the slides advanced. That match is what lets the carousel swap slides unseen.
   */
  progress: MotionValue<number>;
  /** Width of one square panel, as any CSS length. Every other length scales from it. */
  panelWidth?: string;
  /** Perspective distance, in panel widths. Must stay above 1. */
  depth?: number;
  /** Folds the right half onto the left instead. Only the geometry mirrors, not the slide. */
  mirrored?: boolean;
};

/** Which side of the hinge a face sits on. Doubles as the CSS direction its ramps run in. */
export type Side = "left" | "right";

/**
 * The fold on screen. `direction` only changes when a fold starts from rest, so reversing a
 * turn in flight un-folds it instead of mirroring it.
 */
export type Fold = {
  /** The slide it is turning away from. Counts past either end and wraps underneath. */
  from: number;
  /** 1 folds the left half onto the right. -1 is the mirror. */
  direction: 1 | -1;
};

import { motion, useTransform } from "motion/react";

import { DEFAULTS, DOOR } from "../config";
import type { FoldVariantProps } from "./fold-carousel.types";
import { FoldFace } from "./fold-face";
import { FoldStage } from "./fold-stage";
import { panels } from "./panels.utils";
import { SlideLayer } from "./slide-layer";
import { smoothstep } from "./smoothstep.utils";
import { LEAF_TURN, useLeaf } from "./use-leaf";

/**
 * The left half folds onto the still right half, while a second leaf swings the next slide's
 * left half in behind it. Between the two leaves you see through the gap.
 *
 * The outgoing leaf carries `outgoing`'s left half on its front and lands on the right half
 * carrying `incoming`'s right half on its back. At progress 1 the frame is `incoming` on both
 * halves, so the carousel can swap slides with nothing moving.
 */
export function FoldDoor({
  outgoing,
  incoming,
  progress,
  panelWidth,
  depth = DEFAULTS.depth,
  ...props
}: FoldVariantProps) {
  const outgoingAngle = useTransform(
    () => LEAF_TURN * smoothstep(progress.get()),
  );
  // Negative, so it swings in from behind the frame rather than reaching out of it.
  const incomingAngle = useTransform(
    () =>
      DOOR.incomingFrom * (1 - smoothstep(progress.get(), DOOR.incoming)),
  );

  const outgoingLeaf = useLeaf(outgoingAngle, { depth });
  // No overhang: the outgoing leaf's back already paints over this hinge edge. With one, a
  // pixel of the incoming slide would sit on the still half for the first part of the turn.
  const incomingLeaf = useLeaf(incomingAngle, { depth, overhang: false });

  const face = {
    layerWidth: outgoingLeaf.layerWidth,
    layerInset: outgoingLeaf.layerInset,
    screenTop: outgoingLeaf.screenTop,
  };
  const half = { width: panels(1), height: panels(1) };

  return (
    <FoldStage panelWidth={panelWidth} depth={depth} {...props}>
      {/* The incoming leaf's body, edge-on until it swings in. */}
      <motion.div
        style={{ rotateY: incomingAngle, ...half, right: "50%" }}
        className="absolute origin-right bg-black"
      />

      {/* The outgoing leaf's body. Black, so the slivers the magnified fold reaches past the
          screen read as bezel. */}
      <motion.div
        style={{ rotateY: outgoingAngle, ...half }}
        className="origin-right bg-black"
      />

      {/* The still half. */}
      <div style={half} className="relative overflow-hidden bg-black">
        <SlideLayer
          slide={outgoing}
          left={panels(-1)}
          top={panels(0)}
          primary
        />
      </div>

      <FoldFace
        {...face}
        side={incomingLeaf.frontSide}
        slide={incoming}
        clipPath={incomingLeaf.frontClip}
        tilt={incomingLeaf.frontTilt}
      />

      <FoldFace
        {...face}
        side={outgoingLeaf.frontSide}
        slide={outgoing}
        clipPath={outgoingLeaf.frontClip}
        tilt={outgoingLeaf.frontTilt}
      />

      {/* Painted last, so the back comes down on top of the still half instead of meeting
          it edge to edge. */}
      <FoldFace
        {...face}
        side={outgoingLeaf.backSide}
        slide={incoming}
        clipPath={outgoingLeaf.backClip}
        tilt={outgoingLeaf.backTilt}
      />
    </FoldStage>
  );
}

import { type ReactNode, useSyncExternalStore } from "react";
import { type MotionValue, motion, useTransform } from "motion/react";

import { SHADE } from "../config";
import { BLUR_LAYERS, shadeAlpha, shadeTurn } from "./face-ramps.utils";
import type { Side } from "./fold-carousel.types";
import { HINGE_OVERLAP, panels } from "./panels.utils";
import { SlideLayer } from "./slide-layer";

/** CSS gradients interpolate linearly, so the shade curve is sampled into stops. */
const SHADE_STOP_COUNT = 11;

/** The full-turn shade as a gradient, running out from the hinge. */
function shadeGradient(side: Side) {
  const stops = Array.from({ length: SHADE_STOP_COUNT }, (_, index) => {
    const edge = index / (SHADE_STOP_COUNT - 1);
    return `rgb(0 0 0 / ${shadeAlpha(edge).toFixed(3)}) ${(edge * 100).toFixed(1)}%`;
  });

  return `linear-gradient(to ${side}, ${stops.join(", ")})`;
}

const SHADE_GRADIENT: Record<Side, string> = {
  left: shadeGradient("left"),
  right: shadeGradient("right"),
};

/** Nothing to subscribe to. The snapshot only differs between server and client. */
const subscribe = () => () => {};

type BlurLayerProps = {
  slide: ReactNode;
  side: Side;
  slideLeft: string;
  screenTop: string;
  tilt: MotionValue<number>;
  layer: (typeof BLUR_LAYERS)[number];
};

/**
 * One fixed-radius blurred copy of the face, faded in over its slice of the tilt. The radius
 * never animates: a moving blur is re-rasterised every frame, a fixed one only once.
 */
function BlurLayer({
  slide,
  side,
  slideLeft,
  screenTop,
  tilt,
  layer,
}: BlurLayerProps) {
  const opacity = useTransform(tilt, [layer.from, layer.to], [0, 1]);

  return (
    <motion.div
      style={{
        opacity,
        filter: `blur(${panels(layer.radius)})`,
        maskImage: `linear-gradient(to ${side}, transparent ${layer.from * 100}%, black ${layer.to * 100}%)`,
        maskRepeat: "no-repeat",
      }}
      className="absolute inset-0"
    >
      <SlideLayer slide={slide} left={slideLeft} top={screenTop} />
    </motion.div>
  );
}

type FoldFaceProps = {
  /** The slide this face carries. Its side of the hinge picks which half shows. */
  slide: ReactNode;
  side: Side;
  /** The face's outline, from `useLeaf`. Empty while the face points away. */
  clipPath: MotionValue<string>;
  /** 0 flat against the screen to 1 edge-on. */
  tilt: MotionValue<number>;
  layerWidth: string;
  /** How far the layer hangs above and below the frame, to hold the magnified fold. */
  layerInset: string;
  screenTop: string;
};

/**
 * One face of a leaf: a flat copy of the slide clipped to the leaf's outline, with blur
 * copies and a shade on top. Every copy here is hidden from screen readers.
 */
export function FoldFace({
  slide,
  side,
  clipPath,
  tilt,
  layerWidth,
  layerInset,
  screenTop,
}: FoldFaceProps) {
  // The slide spans both halves, so shifting it by a panel picks which half shows.
  const slideLeft = side === "left" ? panels(0) : panels(-1, HINGE_OVERLAP);
  const overhang =
    side === "left"
      ? { right: `calc(50% - ${HINGE_OVERLAP}rem)` }
      : { left: `calc(50% - ${HINGE_OVERLAP}rem)` };
  const shadeOpacity = useTransform(() => shadeTurn(tilt.get()).opacity);
  const shadeStretch = useTransform(() => shadeTurn(tilt.get()).stretch);
  // False through hydration. The blur copies are invisible at rest, so the server HTML skips
  // them, and nothing can turn before hydration anyway.
  const hydrated = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );

  return (
    <motion.div
      style={{
        clipPath,
        width: layerWidth,
        top: layerInset,
        bottom: layerInset,
        ...overhang,
      }}
      // `clip-path` does not clip overflow, and the slide is two panels wide. Without this a
      // face swung past the hinge would paint its other half over the frame.
      className="absolute overflow-hidden"
    >
      <SlideLayer slide={slide} left={slideLeft} top={screenTop} />

      {/* Progressive blur. CSS allows one radius per element, so the shader's per-pixel ramp
          becomes stacked copies. Each spans the whole layer, so the blur spreads into the
          margin instead of stopping at the screen's edge. */}
      {hydrated &&
        BLUR_LAYERS.map((layer) => (
          <BlurLayer
            key={layer.from}
            layer={layer}
            slide={slide}
            side={side}
            slideLeft={slideLeft}
            screenTop={screenTop}
            tilt={tilt}
          />
        ))}

      {/* Shade, above the blur the way the shader darkens the blurred colour. Stretched from
          the dead zone's edge, not only faded, so it never flattens out partway across. */}
      <motion.div
        style={{
          opacity: shadeOpacity,
          scaleX: shadeStretch,
          originX: side === "left" ? 1 - SHADE.deadZone : SHADE.deadZone,
          backgroundImage: SHADE_GRADIENT[side],
        }}
        className="absolute inset-0"
      />
    </motion.div>
  );
}

import type { ComponentProps } from "react";
import { cn } from "cn";

import { DEFAULTS } from "../config";
import { panels } from "./panels.utils";

type FoldStageProps = ComponentProps<"div"> & {
  panelWidth?: string;
  /** Perspective distance, in panel widths. */
  depth: number;
  /** Mirrors the fold, so the right half turns onto a still left half. */
  mirrored?: boolean;
};

/**
 * The box a fold happens in. Its `font-size` is one panel wide, so every length inside is
 * written in `em` and a responsive panel width is plain CSS, with no resize listener.
 */
export function FoldStage({
  panelWidth = DEFAULTS.panelWidth,
  depth,
  mirrored = false,
  className,
  style,
  children,
  ...props
}: FoldStageProps) {
  return (
    <div
      // Slide layers read this to flip their content back, so the slide never mirrors.
      data-mirrored={mirrored || undefined}
      style={{
        fontSize: panelWidth,
        // The origin stays centred, on the hinge, which `useLeaf` assumes.
        perspective: panels(depth),
        height: panels(1),
        // One static flip mirrors every leaf, rotation, and ramp at once.
        transform: mirrored ? "scaleX(-1)" : undefined,
        ...style,
      }}
      className={cn("relative flex items-center", className)}
      {...props}
    >
      {children}
    </div>
  );
}

/*
 * Every length in the fold is written in panel widths. The stage sets `font-size` to one
 * panel, so `1em` is a panel anywhere inside it and the whole rig resizes from that one
 * property. Geometry never uses `rem`, which would stay put while the panel shrank. The
 * hinge overlap is the one exception.
 */

/**
 * How far each face reaches past the hinge, in rem. It covers the fractional pixel where
 * the halves meet, which would otherwise show as a dark hairline down the crease. Absolute,
 * because a device pixel does not shrink with the panel.
 */
export const HINGE_OVERLAP = 0.0625;

/** Trims float noise, which lands in a clip path four times per point. */
function round(value: number) {
  return Number(value.toFixed(5));
}

/**
 * A CSS length of `width` panels plus `rem` rem. A string, because only CSS knows how `em`
 * and `rem` compare.
 */
export function panels(width: number, rem = 0) {
  if (!rem) return `${round(width)}em`;

  return `calc(${round(width)}em ${rem < 0 ? "-" : "+"} ${round(Math.abs(rem))}rem)`;
}

import type { ReactNode } from "react";

import { panels } from "./panels.utils";

type SlideLayerProps = {
  slide: ReactNode;
  /** Where the slide's left edge sits in the parent, as a CSS length. */
  left: string;
  /** Where the slide's top edge sits in the parent, as a CSS length. */
  top: string;
  /** The one copy screen readers hear. A fold paints each slide about ten times. */
  primary?: boolean;
};

/**
 * One copy of a slide, two panels wide, so the hinge cuts the slide instead of restarting
 * it. Shift it with `left` to pick which half shows through the parent.
 */
export function SlideLayer({
  slide,
  left,
  top,
  primary = false,
}: SlideLayerProps) {
  return (
    <div
      aria-hidden={primary ? undefined : true}
      style={{ left, top, width: panels(2), height: panels(1) }}
      // Cancels the stage's mirror for the slide itself, so only the geometry flips.
      className="absolute in-[[data-mirrored]]:-scale-x-100"
    >
      {/* `text-base` puts the font size back from a panel wide to `1rem`. Not `initial`,
          which is a fixed 16px and ignores a page that sizes its own root. The child is
          stretched to fill, so `img` and `next/image` land the same way. */}
      <div className="size-full text-base *:size-full *:object-cover">
        {slide}
      </div>
    </div>
  );
}

type Slice = {
  from: number;
  to: number;
  /**
   * Bends the curve before it is smoothed. 1 is plain smoothstep. Above 1 the part lags and
   * then rushes, below 1 it leads and settles slowly.
   */
  bias?: number;
};

/**
 * Smoothstep across a slice, clamped to 0 to 1. `to` may sit below `from`, which runs the
 * curve backwards.
 */
export function smoothstep(
  value: number,
  { from, to, bias = 1 }: Slice = { from: 0, to: 1 },
) {
  const t = Math.min(1, Math.max(0, (value - from) / (to - from)));
  const bent = t ** bias;

  return bent * bent * (3 - 2 * bent);
}

import { useCallback, useEffect, useRef, useState } from "react";
import { animate, useMotionValue, useReducedMotion } from "motion/react";

import { wrap } from "./wrap.utils";

type FoldEngineOptions = {
  count: number;
  loop: boolean;
  duration: number;
  defaultIndex: number;
  onIndexChange?: (index: number) => void;
};

/** Without a loop, the first and last slides are hard stops. */
function limit(position: number, count: number, loop: boolean) {
  return loop ? position : Math.min(Math.max(position, 0), count - 1);
}

/**
 * Springs `position`, counted in slides, from one whole slide to another on command.
 *
 * Commands aim at a committed target rather than wherever the fold has got to, so five
 * quick presses land five slides on. `index` is the slide it is heading for, so it leads
 * the screen by up to one turn. Looping, `position` is folded back into its first lap each
 * time it lands. With reduced motion it cuts straight to the slide.
 */
export function useFoldEngine({
  count,
  loop,
  duration,
  defaultIndex,
  onIndexChange,
}: FoldEngineOptions) {
  const start = count > 0 ? wrap(defaultIndex, count) : 0;
  const position = useMotionValue(start);
  /** Where the last command sent it, which is not where the fold has got to yet. */
  const target = useRef(start);
  const [index, setIndex] = useState(start);
  const reduced = useReducedMotion();

  // In a ref, so a new callback each render is not a new `go`, which would re-aim a turn in
  // flight.
  const onIndexChangeRef = useRef(onIndexChange);
  useEffect(() => {
    onIndexChangeRef.current = onIndexChange;
  });

  /** Sends the fold to `to` and commits to it, without asking whether it should go. */
  const go = useCallback(
    (to: number) => {
      const previous = wrap(target.current, count);
      target.current = to;

      const nextIndex = wrap(to, count);
      setIndex(nextIndex);
      if (nextIndex !== previous) onIndexChangeRef.current?.(nextIndex);

      /** Back into the first lap, once the fold rests where the lap began. */
      const home = () => {
        const back = loop ? wrap(to, count) : to;
        if (back === to || target.current !== to) return;
        target.current = back;
        position.jump(back);
      };

      if (reduced) {
        position.jump(to);
        home();
        return;
      }

      // The spring keeps the speed the fold already had, so a press mid-turn redirects it
      // instead of restarting it.
      animate(position, to, {
        type: "spring",
        bounce: 0,
        duration,
        onComplete: home,
      });
    },
    [count, loop, duration, reduced, position],
  );

  const settle = useCallback(
    (to: number) => {
      if (!count) return;

      const limited = limit(to, count, loop);
      // A spring to where the fold is already headed still runs and interrupts the one
      // settling, so skip it.
      if (limited === target.current) return;
      go(limited);
    },
    [count, loop, go],
  );

  // A new duration re-aims a turn in flight at the same slide, with no jump.
  useEffect(() => {
    if (position.isAnimating()) go(target.current);
  }, [go, position]);

  // Switching the loop off can strand the fold past the last slide. Bring it back a lap,
  // then turn round for the nearest slide still in range.
  useEffect(() => {
    if (loop || !count) return;

    const last = count - 1;
    const inRange = (slide: number) => slide >= 0 && slide <= last;
    const now = position.get();
    if (inRange(now) && inRange(target.current)) return;

    const at = wrap(now, count);
    const aim = target.current + (at - now);
    if (at !== now) position.jump(at);
    go(inRange(aim) ? aim : Math.min(Math.round(at), last));
  }, [loop, count, go, position]);

  useEffect(() => () => position.stop(), [position]);

  const next = useCallback(() => settle(target.current + 1), [settle]);
  const prev = useCallback(() => settle(target.current - 1), [settle]);

  /** Folds to a slide by number, the short way round when looping. */
  const goTo = useCallback(
    (slide: number) => {
      if (!loop) {
        settle(slide);
        return;
      }

      let step = wrap(slide, count) - wrap(target.current, count);
      if (step > count / 2) step -= count;
      if (step < -count / 2) step += count;

      settle(target.current + step);
    },
    [count, loop, settle],
  );

  return {
    position,
    index,
    count,
    canPrev: loop || index > 0,
    canNext: loop || index < count - 1,
    prev,
    next,
    goTo,
  };
}

import { type MotionValue, useTransform } from "motion/react";

import type { Side } from "./fold-carousel.types";
import { HINGE_OVERLAP, panels } from "./panels.utils";
import { smoothstep } from "./smoothstep.utils";

/** Degrees a leaf turns, from flat on one half to flat on the other. */
export const LEAF_TURN = 180;

/**
 * Closest the far edge may get to the hinge. Exactly edge-on, the overhang's slope divides
 * by zero, and the browser drops an `Infinity` clip path and paints the face over the frame.
 */
const MIN_SPREAD = 1e-4;

type LeafOptions = {
  /** Perspective distance, in panel widths. */
  depth: number;
  /**
   * Whether the faces reach `HINGE_OVERLAP` past the hinge. Turn it off for a leaf whose
   * hinge edge another face already covers, or it leaves a one-pixel line on the other half.
   */
  overhang?: boolean;
};

/** A point on the hinge axis, in panel widths plus rem. */
type Edge = { at: number; rem: number };

/**
 * Clip paths and tilts for the two faces of a leaf turning on `rotateY`.
 *
 * The faces never rotate. Each is a flat layer clipped to the leaf's projected trapezoid, so
 * the slide is never foreshortened. The front shows from 0 to 90°, the back from 90 to 180°,
 * and each clip is empty while its face points away. Assumes the perspective origin sits on
 * the hinge.
 */
export function useLeaf(
  angle: MotionValue<number>,
  { depth, overhang = true }: LeafOptions,
) {
  // Perspective magnifies the turning leaf past the panel, so the layers are taller.
  const layerHeight = depth / (depth - 1);
  // The hinge edge is the one edge never magnified, so the screen's top lines up with it.
  const screenTop = (layerHeight - 1) / 2;

  /** One face's outline, with `hinge` and `hang` in that face's own box. */
  const outline = (deg: number, hinge: Edge, hang: Edge) => {
    const rad = (deg * Math.PI) / 180;
    const scale = depth / (depth - Math.sin(rad));
    // Negative past 90°, which swings the far edge across the hinge: that is the back face.
    const visible = Math.cos(rad) * scale;

    const farX = panels(hinge.at - visible, hinge.rem);
    const hangX = panels(hang.at, hang.rem);
    const farTop = (layerHeight - scale) / 2;

    // Carry the slanted edge along its own slope past the hinge, so the overhang widens the
    // trapezoid instead of tilting it. CSS caps it, since only CSS knows how rem compares.
    const slope = (screenTop - farTop) / Math.max(Math.abs(visible), MIN_SPREAD);
    const carry = `min(${panels(screenTop)}, ${(slope * HINGE_OVERLAP).toFixed(4)}rem)`;

    return `polygon(${farX} ${panels(farTop)}, ${hangX} calc(${panels(screenTop)} + ${carry}), ${hangX} calc(${panels(layerHeight - screenTop)} - ${carry}), ${farX} ${panels(layerHeight - farTop)})`;
  };

  // The front lies left of the hinge and hangs over its box's right edge. The back lies
  // right of it and hangs over its left.
  const front = {
    hinge: { at: 1, rem: 0 },
    hang: { at: 1, rem: overhang ? HINGE_OVERLAP : 0 },
  };
  const back = {
    hinge: { at: 0, rem: HINGE_OVERLAP },
    hang: { at: 0, rem: overhang ? 0 : HINGE_OVERLAP },
  };
  const frontSide: Side = "left";
  const backSide: Side = "right";

  const frontClip = useTransform(() =>
    outline(angle.get(), front.hinge, front.hang),
  );
  const backClip = useTransform(() =>
    outline(angle.get(), back.hinge, back.hang),
  );

  // 0 lying flat to 1 edge-on. The back's runs backwards so it lands at exactly 0, leaving
  // no shade or blur to give away the slide swap.
  const frontTilt = useTransform(() =>
    smoothstep(Math.abs(angle.get()), { from: 0, to: LEAF_TURN / 2 }),
  );
  const backTilt = useTransform(() =>
    smoothstep(Math.abs(angle.get()), { from: LEAF_TURN, to: LEAF_TURN / 2 }),
  );

  return {
    layerWidth: panels(1, HINGE_OVERLAP),
    layerInset: panels(-screenTop),
    screenTop: panels(screenTop),
    frontClip,
    backClip,
    frontTilt,
    backTilt,
    frontSide,
    backSide,
  };
}

/** `value` brought into `[0, size)`, however far past either end it has run. */
export function wrap(value: number, size: number) {
  return ((value % size) + size) % size;
}
